function card(p){let on=state.saved.has(p.id);return '<article class="property-card" tabindex="0" role="link" data-open-property="'+esc(p.id)+'" aria-label="View '+esc(p.title)+'"><div class="property-visual">'+picture(p.image,p.title)+'<span class="photo-tag">'+esc(p.tag||'PROPERTY')+'</span><button type="button" class="savebtn '+(on?'saved':'')+'" data-save="'+esc(p.id)+'" aria-label="'+(on?'Remove saved property':'Save property')+'">'+(on?'♥':'♡')+'</button></div><div class="property-info"><div class="price">'+format(p.price)+' <small>'+(p.intent==='rent'?'/ month':'')+'</small></div><h3>'+esc(p.title)+'</h3><div class="address">⌖ '+esc(p.location)+'</div><div class="property-stats">'+(p.category==='Land'?'<span>▦ '+p.area+' m² plot</span>':p.category==='Commercial'?'<span>▦ '+p.area+' m²</span><span>Commercial</span>':'<span>♧ '+p.beds+' beds</span><span>◉ '+p.baths+' baths</span><span>▦ '+p.area+' m²</span>')+'</div><div class="check-line">◇ Concept listing · Availability unverified</div></div></article>'}
function filterListings(){const f=state.filters;let properties=all().filter(p=>(f.intent==='all'||f.intent==='saved'||p.intent===f.intent)&&(f.intent!=='saved'||state.saved.has(p.id))&&(f.category==='all'||p.category===f.category)&&(!f.term||String(p.title+' '+p.location+' '+p.category).toLowerCase().includes(f.term.toLowerCase()))&&(Number(p.beds)>=Number(f.beds)||p.category==='Land'||p.category==='Commercial')&&(!Number(f.budget)||p.price<=Number(f.budget)));if(f.sort==='price-asc')properties.sort((a,b)=>a.price-b.price);if(f.sort==='price-desc')properties.sort((a,b)=>b.price-a.price);if(f.sort==='area')properties.sort((a,b)=>b.area-a.area);return properties}
